<script lang="ts">
 import { onMount } from 'svelte';
 import SoloGame from '../game/SoloGame.svelte';
 import MultiplayerGame from '../game/MultiplayerGame.svelte';
 import { getLocaleFromPath, localePath, translate } from '../../i18n.js';
 import { initializeAnalytics, trackEvent, trackPageView } from '../../analytics.js';
 import type { Snapshot, ServerEvent, Command } from '@festival/shared';
 let locale=$state<'ko'|'en'>(getLocaleFromPath(location.pathname)), snapshot=$state<Snapshot|null>(null), nickname=$state(''), code=$state(''), error=$state(''), busy=$state(false), connected=$state(false), loading=$state(true), picker=$state(false), copied=$state(false), soloActive=$state(false);
 let socket:WebSocket|undefined, timer:ReturnType<typeof setTimeout>|undefined, disposed=false;
 const pending=new Map<string,ReturnType<typeof setTimeout>>();
 const t=(key:Parameters<typeof translate>[1])=>translate(locale,key);
 let room=$derived(snapshot?.room), session=$derived(room?.session), host=$derived(room?.hostId===snapshot?.me.id);
 let canStart=$derived(!!room&&room.count===room.capacity&&room.members.every(m=>m.online));
 function openDialog(node:HTMLDialogElement){node.showModal();}
 const phases={briefing:'역할 확인',discussion:'단서와 토론',voting:'최종 투표',reveal:'진상 공개'};
 async function api(path:string,body?:unknown){const response=await fetch('/api'+path,{method:body===undefined?'GET':'POST',headers:body===undefined?{}:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)});const data=await response.json();if(!response.ok)throw Object.assign(new Error(data.error??'요청에 실패했어.'),{status:response.status});return data;}
 async function action(fn:()=>Promise<void>){if(busy)return;busy=true;error='';try{await fn();}catch(e){error=e instanceof Error?e.message:'연결을 확인해 줘.';}finally{busy=false;}}
 function connect(){if(disposed)return;socket=new WebSocket(`${location.protocol==='https:'?'wss:':'ws:'}//${location.host}/api/lobby/ws`);socket.onopen=()=>{connected=true;error='';};socket.onmessage=e=>{try{const event=JSON.parse(e.data) as ServerEvent;if(event.type==='snapshot')snapshot=event.data;else {if(event.requestId){clearTimeout(pending.get(event.requestId));pending.delete(event.requestId);busy=false;}if(event.type==='error')error=event.message;}}catch{error='서버 응답을 확인할 수 없어.';}};socket.onclose=()=>{connected=false;for(const t of pending.values())clearTimeout(t);pending.clear();busy=false;if(!disposed)timer=setTimeout(async()=>{try{snapshot=await api('/lobby/state');connect();}catch(e){if((e as {status?:number}).status===401){snapshot=null;error='게스트 로그인이 만료됐어.';}else if(!disposed)connect();}},2000);};socket.onerror=()=>{error='실시간 연결을 확인 중이야.';};}
 function command(type:Command['type'],targetId?:string){if(!connected||busy||!socket)return;error='';busy=true;const requestId=crypto.randomUUID();pending.set(requestId,setTimeout(()=>{pending.delete(requestId);busy=false;error='응답이 지연됐어. 현재 상태를 확인하고 다시 시도해 줘.';},8000));socket.send(JSON.stringify({type,requestId,...(targetId?{targetId}:{})}));}
 async function login(){await action(async()=>{await api('/platform/guest',{nickname});snapshot=await api('/lobby/state');connect();});}
 async function create(scenarioId:string){trackEvent('story_select',{story_id:scenarioId,language:locale});await action(async()=>{await api('/lobby/rooms',{scenarioId});snapshot=await api('/lobby/state');picker=false;});}
 async function join(invite=code){await action(async()=>{await api('/lobby/rooms/join',{code:invite});snapshot=await api('/lobby/state');code='';});}
 async function copy(){try{await navigator.clipboard.writeText(`${location.origin}/?room=${room?.code}`);copied=true;setTimeout(()=>copied=false,2000);}catch{error=`초대 코드: ${room?.code}`;}}
 function changeLocale(next:'ko'|'en'){const previous=locale;if(next===previous)return;locale=next;document.documentElement.lang=next;history.pushState({},'',`${localePath(next,location.pathname)}${location.search}${location.hash}`);trackEvent('language_change',{from_language:previous,to_language:next});requestAnimationFrame(()=>trackPageView(next));}
 onMount(()=>{initializeAnalytics();trackPageView(locale);const syncLocale=()=>{locale=getLocaleFromPath(location.pathname);document.documentElement.lang=locale;requestAnimationFrame(()=>trackPageView(locale));};window.addEventListener('popstate',syncLocale);void(async()=>{try{snapshot=await api('/lobby/state');connect();}catch(e){if((e as {status?:number}).status!==401)error='서버에 연결할 수 없어. 잠시 후 새로고침해 줘.';}finally{code=new URLSearchParams(location.search).get('room')??'';loading=false;}})();return()=>{window.removeEventListener('popstate',syncLocale);disposed=true;clearTimeout(timer);for(const t of pending.values())clearTimeout(t);socket?.close();};});
</script>

<svelte:head><title>{room ? `${room.title} · ${t('brand')}` : t('homeTitle')}</title></svelte:head>
<div class="shell">
 <header class="header"><a class="brand" href={localePath(locale)} aria-label={`${t('brand')} home`}><span class="emblem">✳</span><span>{t('brand')}<small class="brand-subtitle">{t('brandSubtitle')}</small></span></a><div class="flex items-center gap-4"><label class="sr-only" for="language">{t('language')}</label><select class="border border-festival-line bg-festival-panel-input px-2 py-2 text-xs text-festival-text focus-visible:outline-2 focus-visible:outline-festival-gold" id="language" value={locale} onchange={(event)=>changeLocale(event.currentTarget.value as 'ko'|'en')}><option value="ko">한국어</option><option value="en">English</option></select><div class="identity">{#if snapshot}<span class:live={connected} class="dot"></span><span>{snapshot.me.nickname}</span><span class="tag identity-tag">GUEST</span>{:else}<span class="edition">첫 번째 밤의 초대</span>{/if}</div></div></header>
 {#if error}<div class="notice" role="alert">{error}<button class="dismiss" onclick={()=>error=''} aria-label="알림 닫기">×</button></div>{/if}
 {#if loading}<main class="main center"><p>축제의 문을 여는 중…</p></main>
 {:else if soloActive}
 <main class="main"><SoloGame {locale} onExit={() => soloActive=false} /></main>
 {:else if !snapshot}
 <main class="main entrance"><section><p class="eyebrow">AN INVITATION TO THE UNKNOWN</p><h1 class="heading-one entrance-title">{t('invitation')}<br>{t('hiddenStory')} <em class="not-italic text-festival-gold">{t('story')}</em>.</h1><p class="intro">{t('invitationDescription')}</p><div class="ticket"><span>ADMIT ONE</span><span>비밀을 가진 당신에게</span><span>NO. 001</span></div></section><section class="login panel"><p class="eyebrow">ENTER THE FESTIVAL</p><h2 class="heading-two">{t('enterFestival')}</h2><p class="muted">{t('namePrompt')}</p><form onsubmit={e=>{e.preventDefault();void login();}}><label class="input-label" for="nickname">{t('guestName')}</label><input class="input-field" id="nickname" bind:value={nickname} maxlength="20" placeholder={t('namePlaceholder')} required autocomplete="nickname"><button class="primary" disabled={busy||!nickname.trim()}>{busy?'입장 중…':t('guestStart')} <span>↗</span></button></form><button class="secondary" onclick={()=>soloActive=true}>{t('soloPlay')} <span>↗</span></button><p class="fine">가입 없이 시작해. 같은 브라우저에서 다시 접속하면<br>참가 정보가 이어져.</p></section></main>
 {:else if !room}
 <main class="main"><div class="page-heading"><div><p class="eyebrow">THE LOBBY</p><h1 class="heading-one">{t('lobbyTitle')}</h1><p class="muted">{t('lobbyDescription')}</p></div><span class="count">{snapshot.rooms.length}개의 방</span></div>
 <div class="lobby-grid"><section><div class="section-heading"><h2 class="heading-two section-title">{t('openRooms')}</h2><span class="tag">LIVE</span></div>{#if !snapshot.rooms.length}<div class="empty"><span class="empty-symbol">✧</span><h3 class="heading-three">{t('quietFestival')}</h3><p class="empty-copy">{t('createFirstRoom')}</p><button class="secondary secondary-compact" onclick={()=>picker=true}>{t('createRoom')} ↗</button></div>{:else}<div class="rooms">{#each snapshot.rooms as item}<article class="room-card"><div class="section-heading"><span class="eyebrow section-eyebrow">{item.status==='playing'?'IN PROGRESS':'WAITING'}</span><span class="muted">{item.count} / {item.capacity}명</span></div><h3 class="heading-three room-title">{item.title}</h3><p class="muted">초대 코드 <strong>{item.code}</strong></p><button class="secondary" disabled={busy||!connected||item.status==='playing'||item.count>=item.capacity} onclick={()=>join(item.code)}>{item.status==='playing'?'게임 진행 중':item.count>=item.capacity?'정원 마감':'참여하기 ↗'}</button></article>{/each}</div>{/if}</section>
 <aside class="sidebar"><section class="panel"><p class="eyebrow">HOST A STORY</p><h2 class="heading-two sidebar-title">{t('createStory')}</h2><p class="muted">작품을 선택하고<br>우리만의 방을 만들어.</p><button class="primary" disabled={!connected} onclick={()=>picker=true}>{t('createRoom')} <span>＋</span></button></section><section class="panel"><h3 class="heading-three">{t('soloLabel')}</h3><p class="muted">{t('soloDescription')}</p><button class="secondary" onclick={()=>soloActive=true}>{t('startCase')} ↗</button></section><section class="panel"><h3 class="heading-three">{t('invited')}</h3><form onsubmit={e=>{e.preventDefault();void join();}}><label class="input-label join-label" for="code">{t('inviteCodeLabel')}</label><input class="input-field" id="code" bind:value={code} maxlength="6" placeholder="예: A1B2C3" autocomplete="off"><button class="secondary" disabled={busy||!connected||code.trim().length!==6}>{t('joinByCode')} ↗</button></form></section></aside></div></main>
 {:else if !session}
 <main class="main"><p class="eyebrow">BEFORE THE CURTAIN RISES</p><div class="page-heading"><div><h1 class="heading-one page-title">{room.title}</h1><p class="muted">{room.scenario.kind==='demo'?'기능 검증용 테스트 시나리오':'오리지널 스토리'} · {room.capacity}인 · 약 {room.scenario.minutes}분</p></div><button class="text-button" disabled={busy||!connected} onclick={()=>command('leave')}>방 나가기 ↗</button></div><div class="lobby-grid"><section class="panel"><div class="section-heading"><h2 class="heading-two section-title">참가자</h2><span class="count">{room.count} / {room.capacity}</span></div><div class="members">{#each room.members as member}<div class="member"><span class="avatar">{member.nickname.slice(0,1)}</span><div class="member-info"><strong class="member-name">{member.nickname}</strong><small class="member-role">{member.id===snapshot.me.id?'나':member.online?'접속 중':'재접속 대기 중'}</small></div>{#if member.id===room.hostId}<span class="tag gold">방장</span>{/if}<span class:live={member.online} class="dot member-status"></span></div>{/each}{#each Array(room.capacity-room.count) as _}<div class="member vacant"><span class="avatar vacant-avatar">＋</span><span>누군가의 입장을 기다리는 중</span></div>{/each}</div></section><aside class="sidebar"><section class="panel"><p class="eyebrow">INVITE YOUR FRIENDS</p><h2 class="heading-two sidebar-title">초대 코드</h2><p class="invite-code">{room.code}</p><button class="secondary" onclick={copy}>{copied?'초대 링크 복사 완료':'초대 링크 복사 ↗'}</button></section><section class="panel"><p class="muted">{canStart?'모든 참가자가 모였어. 이야기를 시작해도 좋아.':'필요한 인원이 모두 접속하면 시작할 수 있어.'}</p>{#if host}<button class="primary" disabled={!canStart||!connected||busy} onclick={()=>command('start')}>게임 시작 <span>→</span></button>{:else}<p class="fine">방장이 게임을 시작하기를 기다리는 중</p>{/if}</section></aside></div></main>
 {:else}
 <MultiplayerGame {room} {session} {host} {busy} {connected} {phases} {canStart} {copied} meId={snapshot.me.id} onCommand={command} onCopy={copy} />
 {/if}
 <footer class="footer"><span>THE STRANGE FESTIVAL</span><span class="footer-tagline">{t('footerTagline')}</span>{#if snapshot}<span class:offline={!connected}>{connected?t('connected'):t('disconnected')}</span>{:else}<span>MURDER MYSTERY CLUB</span>{/if}</footer>
</div>
{#if picker&&snapshot}<div class="modal-backdrop" role="presentation"><dialog class="modal" use:openDialog oncancel={()=>picker=false} aria-labelledby="picker-title"><div class="section-heading"><p class="eyebrow section-eyebrow">CHOOSE YOUR STORY</p><button class="dismiss" onclick={()=>picker=false} aria-label="작품 선택 닫기">×</button></div><h2 class="modal-title" id="picker-title">{t('chooseStory')}</h2><div class="tabs"><span class="tab selected">오리지널 스토리</span><button class="tab tab-button" disabled title="준비 중">창작마당 <span class="tag tab-tag">준비 중</span></button></div><div class="scenario-list">{#each snapshot.scenarios as story}<button class="scenario" disabled={!story.available||busy||!connected} onclick={()=>create(story.id)}><div><span class="eyebrow scenario-label">{story.kind==='demo'?'PLAYTEST':'ORIGINAL'}</span><h3 class="heading-three scenario-title">{story.title}</h3><p class="scenario-description">{story.subtitle}</p><small class="scenario-meta">{story.players}인 · 약 {story.minutes}분{!story.available?' · 인원·시간 미정의 임시 표시':''}</small></div><span class="scenario-status">{story.available?'↗':'집필 중'}</span></button>{/each}</div></dialog></div>{/if}
